package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.FrontchannelLogoutUriVO;

class FrontchannelLogoutUriValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of frontchannel logout uri of oauth client")
  void test_frontchannel_logout_uri_value_holder_assign_plain_value() {
    Object holder = new Object();
    FrontchannelLogoutUriValueHolder<Object> value = new FrontchannelLogoutUriValueHolder<>(holder);
    Assertions.assertSame(holder, value.frontchannelLogoutUri("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getFrontchannelLogoutUriValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getFrontchannelLogoutUri().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.frontchannelLogoutUriNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getFrontchannelLogoutUriValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getFrontchannelLogoutUri().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of frontchannel logout uri of oauth client")
  void test_frontchannel_logout_uri_value_holder_assign_value_object() {
    Object holder = new Object();
    FrontchannelLogoutUriValueHolder<Object> value = new FrontchannelLogoutUriValueHolder<>(holder);
    FrontchannelLogoutUriVO vo = FrontchannelLogoutUriVO.from("one");
    Assertions.assertFalse(value.getFrontchannelLogoutUriValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.frontchannelLogoutUri(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getFrontchannelLogoutUriValue().orElseThrow());
    Assertions.assertSame(holder, value.frontchannelLogoutUri(Optional.empty()));
    Assertions.assertFalse(value.getFrontchannelLogoutUriValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.frontchannelLogoutUri(Optional.of(vo)));
    Assertions.assertSame(vo, value.getFrontchannelLogoutUriValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of frontchannel logout uri of oauth client against the original")
  void test_frontchannel_logout_uri_value_holder_read() {
    Object holder = new Object();
    FrontchannelLogoutUriValueHolder<Object> value = new FrontchannelLogoutUriValueHolder<>(holder);
    FrontchannelLogoutUriVO vo = FrontchannelLogoutUriVO.from("one");
    FrontchannelLogoutUriVO other = FrontchannelLogoutUriVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getFrontchannelLogoutUriValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readFrontchannelLogoutUri(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readFrontchannelLogoutUri(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.frontchannelLogoutUri(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readFrontchannelLogoutUri(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readFrontchannelLogoutUri(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of frontchannel logout uri of oauth client")
  void test_frontchannel_logout_uri_value_holder_unset() {
    Object holder = new Object();
    FrontchannelLogoutUriValueHolder<Object> value = new FrontchannelLogoutUriValueHolder<>(holder);
    FrontchannelLogoutUriVO vo = FrontchannelLogoutUriVO.from("one");
    value.frontchannelLogoutUri(vo);
    Assertions.assertSame(holder,
        value.unsetFrontchannelLogoutUriIfMatches("frontchannelLogoutUri_other"));
    Assertions.assertTrue(value.getFrontchannelLogoutUriValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetFrontchannelLogoutUriIfMatches("frontchannelLogoutUri"));
    Assertions.assertFalse(value.getFrontchannelLogoutUriValue().isPresent(),
        "The field name must clear the value");
    value.frontchannelLogoutUri(vo);
    Assertions.assertSame(holder, value.unsetFrontchannelLogoutUri());
    Assertions.assertFalse(value.getFrontchannelLogoutUriValue().isPresent(),
        "Unset must clear the value");
  }
}
